(function(outputs, steps, params, stepResult, assertEqual) {

    describe("RestUtil - validateContent tests", () => {
        const api = new x_neyu_google_nyu.RestUtil();

        it("should return an object of missing required keys", () => {
            const spec = {
                keyA: {
                    required: true
                },
                keyB: {
                    required: false
                }
            };
            const content = {
                keyB: "something"
            };
            const result = api.validateContent(spec, content);
            expect(result).toBeDefined();
            expect("keyA" in result).toBe(true);
            expect(result["keyA"].error).toBe("Missing required input 'keyA'");
        });

        it("should have the hasToken method", () => {
            expect("ensureToken" in api).toBe(true);
        });

        it("Should return an error if a input value is not in the spec's enum", () => {
            const spec = {
                keyA: {
                    required: true,
                    enum: ["a", "b"]
                }
            };
            const content = {
                keyA: "c"
            };

            const result = api.validateContent(spec, content);
            expect(result).toBeDefined();
            expect("keyA" in result).toBe(true);
            expect(result["keyA"].value).toBe("c");
            expect(result["keyA"].error).toBe("Value 'c' is not a valid input for property 'keyA'");
        });

        it("should return null if all conditions are satified", () => {
            const spec = {
                keyA: {
                    required: true,
                    enum: ["a", "b"]
                },
                keyB: {
                    required: true
                }
            };
            const content = {
                keyA: "a",
                keyB: "foo"
            };

            expect(api.validateContent(spec, content)).toBe(null);
        });

        it("should return an error if there are extra inputs.", () => {
            const spec = {
                keyA: {
                    required: true,
                    enum: ["a", "b"]
                },
                keyB: {
                    required: false
                }
            };
            const content = {
                keyA: "a",
                keyB: "b",
                keyC: "c"
            };

            const result = api.validateContent(spec, content);
            expect(result).toBeDefined();
            expect("keyC" in result).toBe(true);
            expect(result["keyC"].value).toBe("c");
            expect(result["keyC"].error).toBe("Property 'keyC' is not a valid input");
        });

        [
            null,
            {}
        ].forEach((testSpec) => {
            it("Should throw an error if the passed in spec is null or empty", () => {
                expect(() => {
                    api.validateContent(testSpec, {
                        key: "value"
                    });
                }).toThrowError("specification is required");
            });
        });

        [
            null,
            {}
        ].forEach((testContent) => {
            it("Should throw an error if the passed in content is null or empty", () => {
                expect(() => {
                    api.validateContent({
                        "key": {}
                    }, testContent);
                }).toThrowError("content is required");
            });
        });

    });

})(outputs, steps, params, stepResult, assertEqual);
// uncomment the next line to execute this script as a jasmine test
jasmine.getEnv().execute();
